import{_ as t,o as s,c as r,a4 as e}from"./chunks/framework.DAe4SYBh.js";const d=JSON.parse('{"title":"调整内存和 MMZ 分配","description":"","frontmatter":{},"headers":[],"relativePath":"goke/common/调整内存和MMZ分配.md","filePath":"goke/common/调整内存和MMZ分配.md"}'),a={name:"goke/common/调整内存和MMZ分配.md"};function n(m,o,l,p,_,g){return s(),r("div",null,[...o[0]||(o[0]=[e('<h1 id="调整内存和-mmz-分配" tabindex="-1">调整内存和 MMZ 分配 <a class="header-anchor" href="#调整内存和-mmz-分配" aria-label="Permalink to “调整内存和 MMZ 分配”">​</a></h1><p>以 OS 内存从 32M 调整到 40M 为例。</p><h2 id="_1-修改-bootargs" tabindex="-1">1. 修改 Bootargs <a class="header-anchor" href="#_1-修改-bootargs" aria-label="Permalink to “1. 修改 Bootargs”">​</a></h2><p>在 sdk/configs/xm72020330/prebuilts/spi_bootargs_tiny.txt 中，修改 mem</p><p>bootargs=<strong>mem=32M</strong> console=ttyAMA0,115200 root=/dev/mtdblock3 rootfstype=jffs2 rw mtdparts=sfc:512K(boot),512K(bootargs),4M(kernel),11M(rootfs) lpj=9838592</p><p>修改为</p><p>bootargs=<strong>mem=40M</strong> console=ttyAMA0,115200 root=/dev/mtdblock3 rootfstype=jffs2 rw mtdparts=sfc:512K(boot),512K(bootargs),4M(kernel),11M(rootfs) lpj=9838592</p><p>如果是快启版本，需要在 sdk/configs/xm72020330/prebuilts/spi_bootargs_buildin_tiny.txt 中修改</p><p>bootargs=<strong>mem=32M</strong> console=ttyAMA0,115200 loglevel=0 root=/dev/mtdblock3 rootfstype=jffs2 rw mtdparts=sfc:512K(boot),512K(bootargs),4M(kernel),11M(rootfs) mmz_allocator=xmedia mmz=anonymous,0,<strong>0x42000000</strong>,<strong>32M</strong> chip=xm72020330 sensors=gc2053 g_cmos_yuv_flag=0 board=demo save_power=0 lpj=9838592 max_node_num=20</p><p>=&gt;</p><p>bootargs=<strong>mem=40M</strong> console=ttyAMA0,115200 loglevel=0 root=/dev/mtdblock3 rootfstype=jffs2 rw mtdparts=sfc:512K(boot),512K(bootargs),4M(kernel),11M(rootfs) mmz_allocator=xmedia mmz=anonymous,0,<strong>0x42800000</strong>,<strong>24M</strong> chip=xm72020330 sensors=gc2053 g_cmos_yuv_flag=0 board=demo save_power=0 lpj=9838592 max_node_num=20</p><h2 id="_2-调整加载驱动时的参数" tabindex="-1">2. 调整加载驱动时的参数 <a class="header-anchor" href="#_2-调整加载驱动时的参数" aria-label="Permalink to “2. 调整加载驱动时的参数”">​</a></h2><p>在使用 load 脚本加载媒体驱动时，调整参数</p><p>./load xm72020330 -i -sensor gc2053 <strong>-osmem 40</strong></p>',14)])])}const i=t(a,[["render",n]]);export{d as __pageData,i as default};
